import {fields,aliases,parseInput,autoMap,transform,toCSV,sample} from './pipeline.js';
const $=id=>document.getElementById(id);let rows=[],mapping={},result=null,page=0;const pageSize=8;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v.toLocaleString();
let history=[];try{const stored=JSON.parse(localStorage.getItem('mediaflow-runs-v1')||'[]');if(Array.isArray(stored))history=stored.filter(x=>x&&typeof x.at==='string'&&['input','accepted','rejected','duplicates'].every(k=>Number.isSafeInteger(x[k])&&x[k]>=0)).slice(0,20);}catch{}
function message(text,error=false){$('message').textContent=text;$('message').className='small '+(error?'error':'success');}
function read(){rows=parseInput($('source').value,$('format').value);mapping=autoMap(rows);const keys=[...new Set(rows.flatMap(Object.keys))];$('mapping').innerHTML='<p class="mapping-head">Map your columns</p>'+fields.map(f=>`<div class="map-row"><label for="map-${f}">${f}</label><select id="map-${f}" data-field="${f}"><option value="">Choose column…</option>${keys.map(k=>`<option value="${esc(k)}" ${mapping[f]===k?'selected':''}>${esc(k)}</option>`).join('')}</select></div>`).join('');$('mapping').querySelectorAll('select').forEach(s=>s.onchange=()=>{mapping[s.dataset.field]=s.value;});$('run').disabled=false;message(`${fmt(rows.length)} records read. Review field mappings, then run.`);}
function invalidate(){rows=[];mapping={};$('mapping').innerHTML='';$('run').disabled=true;message('Source changed. Read data again before running.');}
function loadSample(){$('format').value='json';$('source').value=JSON.stringify(sample,null,2);read();}
$('source').oninput=invalidate;$('format').onchange=invalidate;$('sample').onclick=loadSample;
$('map').onclick=()=>{try{read();}catch(e){invalidate();message(e.message,true);}};
$('file').onchange=async()=>{const f=$('file').files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('Choose a file smaller than 2 MB.');if(!/\.(csv|json)$/i.test(f.name))throw Error('Choose a CSV or JSON file.');$('source').value=await f.text();$('format').value=f.name.toLowerCase().endsWith('.csv')?'csv':'json';read();}catch(e){invalidate();message(e.message,true);}finally{$('file').value='';}};
$('run').onclick=()=>{try{if(!rows.length)read();const start=performance.now();result=transform(rows,mapping);page=0;$('search').value='';$('view').value='accepted';const ms=Math.max(1,Math.round(performance.now()-start));render();const summary={at:new Date().toISOString(),input:result.input,accepted:result.accepted.length,rejected:result.rejected.length,duplicates:result.duplicates.length};history=[summary,...history].slice(0,20);let saved=true;try{localStorage.setItem('mediaflow-runs-v1',JSON.stringify(history));}catch{saved=false;}renderHistory();message(`Completed in ${ms} ms. ${summary.accepted} accepted, ${summary.rejected} rejected, ${summary.duplicates} duplicates.${saved?'':' History could not be saved in this browser.'}`);}catch(e){message(e.message,true);}};
function render(){const {input,accepted,rejected,duplicates}=result;$('ingested').textContent=fmt(input);$('accepted').textContent=fmt(accepted.length);$('issues').textContent=fmt(rejected.length+duplicates.length);const pct=Math.round(accepted.length/input*100);$('quality-label').textContent=`${pct}% accepted`;
 const channels={};accepted.forEach(r=>channels[r.platform]=(channels[r.platform]||0)+r.views);const max=Math.max(1,...Object.values(channels));
 $('quality').innerHTML=`<div class="quality-bar" role="img" aria-label="${pct}% accepted, ${rejected.length} rejected, ${duplicates.length} duplicates"><span class="good" style="width:${accepted.length/input*100}%"></span><span class="bad" style="width:${rejected.length/input*100}%"></span><span class="dupe" style="width:${duplicates.length/input*100}%"></span></div><div class="legend"><span><i class="dot" style="background:#2863e0"></i><b>${accepted.length}</b> accepted</span><span><i class="dot" style="background:#dc7d43"></i><b>${rejected.length}</b> rejected</span><span><i class="dot" style="background:#91a2b6"></i><b>${duplicates.length}</b> duplicates</span></div><p class="quality-caption">VIEWS BY PLATFORM · ACCEPTED RECORDS ONLY</p>${Object.entries(channels).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<div class="channel-row"><span>${esc(c)}</span><progress max="${max}" value="${v}" aria-label="${esc(c)} views"></progress><span>${fmt(v)}</span></div>`).join('')||'<p class="muted small">No accepted records. Review rejected rows below.</p>'}`;
 $('csv').disabled=!accepted.length;$('json').disabled=!accepted.length;$('report').disabled=false;renderRecords();}
function renderRecords(){if(!result)return;const type=$('view').value,query=$('search').value.toLowerCase();const selected=result[type].filter(r=>JSON.stringify(r).toLowerCase().includes(query));const pages=Math.ceil(selected.length/pageSize);page=Math.min(page,Math.max(0,pages-1));const visible=selected.slice(page*pageSize,(page+1)*pageSize);
 let html;if(!visible.length)html='<p class="muted small">No matching records.</p>';else if(type==='accepted')html='<table><thead><tr><th>Content</th><th>Platform</th><th>Published</th><th>Views</th><th>Engagement %</th></tr></thead><tbody>'+visible.map(r=>`<tr><td class="title"><strong>${esc(r.title)}</strong><br><span class="muted small">${esc(r.id)}</span></td><td><span class="pill">${esc(r.platform)}</span></td><td>${r.published_at}</td><td>${fmt(r.views)}</td><td>${r.engagement_rate===null?'—':r.engagement_rate.toFixed(2)+'%'}</td></tr>`).join('')+'</tbody></table>';else html='<table><thead><tr><th>Source row</th><th>Issue</th><th>Original record</th></tr></thead><tbody>'+visible.map(r=>`<tr><td>${r.row}</td><td class="title">${esc(r.errors.join('; '))}</td><td><details><summary>Inspect record</summary><pre>${esc(JSON.stringify(r.raw,null,2))}</pre></details></td></tr>`).join('')+'</tbody></table>';
 $('records').innerHTML=html;$('page-label').textContent=`${selected.length} records${pages?' · '+(page+1)+' / '+pages:''}`;$('prev').disabled=page===0;$('next').disabled=page+1>=pages;
}
$('view').onchange=$('search').oninput=()=>{page=0;renderRecords();};$('prev').onclick=()=>{page--;renderRecords();};$('next').onclick=()=>{page++;renderRecords();};
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('csv').onclick=()=>download('mediaflow-clean.csv',toCSV(result.accepted),'text/csv;charset=utf-8');$('json').onclick=()=>download('mediaflow-clean.json',JSON.stringify(result.accepted,null,2),'application/json');$('report').onclick=()=>download('mediaflow-quality-report.json',JSON.stringify(result,null,2),'application/json');
function renderHistory(){$('history-count').textContent=history.length;$('history-list').innerHTML=history.length?'<div class="table-wrap"><table><thead><tr><th>Run time</th><th>Input</th><th>Accepted</th><th>Rejected</th><th>Duplicates</th></tr></thead><tbody>'+history.map(r=>`<tr><td>${esc(new Date(r.at).toLocaleString())}</td><td>${r.input}</td><td>${r.accepted}</td><td>${r.rejected}</td><td>${r.duplicates}</td></tr>`).join('')+'</tbody></table></div>':'<p class="muted">Run a pipeline to create your first summary.</p>';$('clear').disabled=!history.length;}
$('clear').onclick=()=>{history=[];try{localStorage.removeItem('mediaflow-runs-v1');}catch{}renderHistory();};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(n=>{n.classList.toggle('active',n===b);if(n===b)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});['pipeline','history','schema'].forEach(id=>$(id).hidden=id!==b.dataset.tab);});
const rules={id:'Nonempty text; unique with platform',title:'Nonempty text',platform:'Nonempty text, normalized to lowercase',published_at:'Real date, YYYY-MM-DD',views:'Nonnegative safe integer',engagements:'Nonnegative safe integer'};$('contract').innerHTML=fields.map(f=>`<tr><td>${f}</td><td>${rules[f]}</td><td>${aliases[f].join(', ')}</td></tr>`).join('');loadSample();renderHistory();
